import sys; sys.path.insert(0, __import__("pathlib").Path(__file__).resolve().parents[1].as_posix())
from explications import *

ENTREES = [
    ("## 🗝️ Vocabulaire", 'fin', apropos("Une machine peut « penser » ? Comment un petit circuit comme un Arduino peut-il décider d'allumer une LED ?", "Il ne pense pas : il **exécute un programme**, c'est-à-dire une suite d'**instructions** que **tu écris**. Le programme lui dit, par exemple : « allume la broche 13, attends une seconde, éteins-la ».\n\nDans cette séance, tu apprends à **écrire**, **téléverser** et **tester** ton premier programme (un « sketch ») sur une carte Arduino.")),
    ("## 1.", 'fin', clair("La carte **Arduino Uno** contient un **microcontrôleur** (ATmega328P) : un petit ordinateur sur une puce. On y raccorde :\n\n- le **câble USB** (alimentation et programmation) ;\n- les **broches numériques** D0 à D13 (entrées ou sorties 0 / 1) ;\n- les **broches analogiques** A0 à A5 (mesure de tensions) ;\n- les broches **5 V**, **3,3 V** et **GND** (alimentation).\n\nLa **LED « L »** est reliée à la broche **D13** : c'est elle que s'allume avec le programme Blink.") + "\n" + verifie(
        ("À quoi sert le câble USB de l'Arduino ?", "À **alimenter** la carte et à **téléverser** le programme depuis l'ordinateur."),
        ("Quelle LED de la carte est reliée à D13 ?", "La LED **« L »**."),
        ("Quelle différence entre broches numériques et broches analogiques ?", "Les **numériques** ne connaissent que **0 ou 1** ; les **analogiques** mesurent une **tension variable**.")) + "\n" + retenir("Le microcontrôleur exécute le programme ; D0–D13 numériques, A0–A5 analogiques.")),
    ("## 2.", 'fin', clair("L'**IDE Arduino** est le logiciel où tu **écris**, **vérifies** (✓) et **téléverses** (→) ton programme. Avant de téléverser, deux réglages **obligatoires** :\n\n1. choisir la **carte** : *Arduino Uno* ;\n2. choisir le **port** : celui où l'Arduino est branché (COM3, COM4…).\n\n**Vérifier** (compiler) contrôle la syntaxe ; **téléverser** envoie le programme dans la carte.") + "\n" + verifie(
        ("Quels sont les deux réglages à faire avant de téléverser ?", "Le **type de carte** (Arduino Uno) et le **port** de communication."),
        ("Quelle différence entre « Vérifier » et « Téléverser » ?", "**Vérifier** contrôle le programme ; **téléverser** l'envoie dans la carte."),
        ("Le port n'apparaît pas. Que vérifies-tu ?", "Que le **câble USB** est bien branché (et que c'est un câble de **données**).")) + "\n" + retenir("Choisir carte et port, vérifier, puis téléverser.")),
    ("## 3.", 'fin', clair("Un sketch comporte **toujours deux parties** :\n\n- `setup()` : exécuté **une seule fois**, au démarrage. On y **configure** les broches (`pinMode`).\n- `loop()` : exécuté **en boucle, sans fin**. C'est le **comportement permanent**.\n\nPour allumer puis éteindre une LED : `digitalWrite(broche, HIGH)` allume, `digitalWrite(broche, LOW)` éteint, `delay(1000)` attend **1 seconde** (1000 ms).") + "\n" + erreurs("Oublier le point-virgule `;` à la fin d'une instruction.", "Oublier `pinMode(13, OUTPUT)` dans `setup()`.", "Confondre `HIGH` (allumé) et `LOW` (éteint).") + "\n" + verifie(
        ("Combien de fois `setup()` est-elle exécutée ?", "**Une seule fois**, au démarrage."),
        ("Que fait `delay(500)` ?", "Elle **attend 500 millisecondes** (0,5 seconde) avant la suite."),
        ("Quelle instruction fait clignoter une LED à 1 Hz ?", "Allumer (`HIGH`), `delay(500)`, éteindre (`LOW`), `delay(500)` : cela donne **un clignotement par seconde**.")) + "\n" + retenir("`setup()` une fois, `loop()` sans fin.", "`pinMode`, `digitalWrite`, `delay`.")),
    ("## 4.", 'fin', clair("La LED reliée **à l'extérieur** doit toujours être **protégée par une résistance**, comme en S02. Le chemin est : **broche D13 → résistance → LED (anode vers D13) → GND**.\n\nSi la LED ne s'allume pas, vérifie dans l'ordre : le **sens** de la LED, la **résistance**, la **broche** utilisée, le **GND** relié.") + "\n" + verifie(
        ("Pourquoi faut-il une résistance en série avec la LED ?", "Pour **limiter le courant** : sans elle, la LED ou la broche risque d'être détruite."),
        ("Où se branche la patte longue (anode) de la LED ?", "Du côté de la **broche D13** (via la résistance), la patte courte allant au **GND**.")) + "\n" + retenir("D13 → résistance → LED → GND.")),
    ("## 5.", 'fin', clair("Le **Serial Monitor** est une « fenêtre de discussion » entre l'Arduino et l'ordinateur. Dans le programme, `Serial.begin(9600)` ouvre la communication et `Serial.println(\"texte\")` envoie un message. La **vitesse** (9600 bauds) doit être **la même** dans le programme et dans la fenêtre du Serial Monitor, sinon tu vois des **caractères illisibles**.") + "\n" + verifie(
        ("À quoi sert le Serial Monitor ?", "À **afficher** les messages envoyés par l'Arduino et à **tester** ou **déboguer** un programme."),
        ("Le moniteur affiche des caractères bizarres. Quelle est la cause la plus probable ?", "La **vitesse** choisie (bauds) n'est pas la même que dans `Serial.begin()`.")) + "\n" + retenir("`Serial.begin(9600)` dans le programme = 9600 bauds dans le moniteur.")),
    ("## 7.", 'fin', clair("Quand l'IDE affiche une **erreur en rouge**, **ne panique pas** : lis le message, trouve la **ligne** indiquée et cherche d'abord les erreurs les plus fréquentes : **point-virgule** oublié, **accolade** non fermée, **faute de frappe** dans un nom (`pinmode` au lieu de `pinMode`), **majuscule** oubliée.") + "\n" + verifie(
        ("Le message dit « expected ';' before '}' ». Que faut-il faire ?", "Ajouter un **point-virgule** à la fin de l'instruction **juste avant** l'accolade."),
        ("Pourquoi `pinmode(13, OUTPUT)` provoque-t-elle une erreur ?", "L'Arduino distingue **majuscules et minuscules** : il faut écrire `pinMode`.")) ),
]
